        ((x + int1), (y + int2)),
        ((x - int1), (y + int2)),
        ((x + int1), (y - int2)),
        ((x - int1), (y - int2)),
        ((x + int2), (y + int1)),
        ((x - int2), (y + int1)),
        ((x + int2), (y - int1)),
        ((x - int2), (y - int1))
    ];
}

